const body = $json.body ?? $json;
const allowedUnits = new Set(['g','kg','ml','l','piece','tbsp','tsp']);
const allowedTimes = new Set(['quick','medium','complex']);
const allowedCuisines = new Set(['German','Italian','Japanese','Indian','Gourmet','Fusion']);
const allowedDiets = new Set(['Vegetarian','Vegan','Keto','None']);

if (!Array.isArray(body.ingredients) || body.ingredients.length < 1) throw new Error('INVALID_INPUT: at least one ingredient is required');
for (const ingredient of body.ingredients) {
  if (typeof ingredient.name !== 'string' || !ingredient.name.trim()) throw new Error('INVALID_INPUT: ingredient name');
  if (!Number.isFinite(Number(ingredient.quantity)) || Number(ingredient.quantity) <= 0) throw new Error('INVALID_INPUT: ingredient quantity');
  if (!allowedUnits.has(ingredient.unit)) throw new Error('INVALID_INPUT: ingredient unit');
}
const p = body.preferences ?? {};
if (!Number.isInteger(p.portions) || p.portions < 1 || p.portions > 12) throw new Error('INVALID_INPUT: portions');
if (!Number.isInteger(p.cookingPeople) || p.cookingPeople < 1 || p.cookingPeople > 3) throw new Error('INVALID_INPUT: cookingPeople');
if (!allowedTimes.has(p.timeCategory)) throw new Error('INVALID_INPUT: timeCategory');
if (!allowedCuisines.has(p.cuisine)) throw new Error('INVALID_INPUT: cuisine');
if (!allowedDiets.has(p.diet)) throw new Error('INVALID_INPUT: diet');

return [{ json: { request: body, receivedAt: new Date().toISOString(), quotaPolicy: { perIpPerDay: 3, systemPerDay: 12 } } }];

/* Development sufficiency guard. Convert heterogeneous units to a coarse food-volume equivalent so obviously undersized requests can be rejected before quota/AI work. Replace this heuristic with ingredient-aware nutrition/density logic when the real provider is connected. */
const { request } = $json;
const equivalentPerUnit = { g: 1, kg: 1000, ml: 1, l: 1000, piece: 80, tbsp: 15, tsp: 5 };
const minimumEquivalentPerPortion = 150;
const suppliedEquivalent = request.ingredients.reduce((total, ingredient) => {
  const factor = equivalentPerUnit[ingredient.unit] ?? 0;
  return total + Number(ingredient.quantity) * factor;
}, 0);
const requiredEquivalent = request.preferences.portions * minimumEquivalentPerPortion;
const insufficient = suppliedEquivalent < requiredEquivalent;

return [{
  json: {
    ...$json,
    sufficiency: {
      insufficient,
      suppliedEquivalent: Math.round(suppliedEquivalent * 100) / 100,
      requiredEquivalent,
      minimumEquivalentPerPortion,
      heuristic: 'development-only'
    }
  }
}];

const { request } = $json;
const ingredients = request.ingredients.map(i => `${i.quantity}${i.unit} ${i.name}`).join(', ');
const prompt = `Return ONLY valid JSON with a top-level recipes array containing exactly 3 recipes. Each must use at least 70% of supplied ingredients and at most 3 extra base ingredients. Include title, cuisine, diet, cookingTimeMinutes, portions, usedIngredientRatio, missingIngredients, ingredients, nutritionPerPortion {calories,proteinG,carbsG,fatG}, and chronological steps {order,title,instruction,cook,parallelGroup?}. Preferences: ${JSON.stringify(request.preferences)}. Ingredients: ${ingredients}.`;
return [{ json: { ...$json, aiPrompt: prompt } }];

/* Replace this development stub with your credential-backed AI node. */
const request = $json.request;
const base = { cuisine: request.preferences.cuisine, diet: request.preferences.diet, cookingTimeMinutes: request.preferences.timeCategory === 'quick' ? 20 : request.preferences.timeCategory === 'medium' ? 35 : 60, portions: request.preferences.portions, usedIngredientRatio: 1, missingIngredients: [], ingredients: request.ingredients.map(i => ({...i, suppliedByUser: true})), nutritionPerPortion: { calories: 500, proteinG: 20, carbsG: 55, fatG: 18 }, steps: [{ order: 1, title: 'Prepare ingredients', instruction: 'Prepare and measure all ingredients before cooking.', cook: 1 }, { order: 2, title: 'Cook', instruction: 'Cook the ingredients using the selected cuisine style and season to taste.', cook: Math.min(2, request.preferences.cookingPeople) }] };
const recipes = ['Pantry skillet', 'Kitchen bowl', 'Quick bake'].map((title, index) => ({ ...base, title: `${title} ${index + 1}` }));
return [{ json: { request, recipes } }];

const recipes = $json.recipes;
if (!Array.isArray(recipes) || recipes.length !== 3) throw new Error('AI_PROVIDER_ERROR: workflow must produce exactly 3 recipes');
for (const recipe of recipes) {
  if (Number(recipe.usedIngredientRatio) < 0.7) throw new Error('AI_PROVIDER_ERROR: recipe uses less than 70% of user ingredients');
  if (!Array.isArray(recipe.missingIngredients) || recipe.missingIngredients.length > 3) throw new Error('AI_PROVIDER_ERROR: too many missing ingredients');
  if (!Array.isArray(recipe.steps) || recipe.steps.length < 1) throw new Error('AI_PROVIDER_ERROR: missing directions');
}
return items;
